137	pub const DARK_NAME: &str = "Suspense Dark";
138	pub const LIGHT_NAME: &str = "Suspense Light";
139	
140	/// The palette of the mode showing, at that mode's brightness.
141	pub fn palette(cx: &App) -> &'static Palette {
142	    let dark = cx.theme().is_dark();
143	    shifted(dark, brightness_of(dark, cx))
144	}
145	
146	/// The grey the Brightness slider crosses from dark mode to light mode on:
147	/// #777777, lightness 50 in CIELAB, halfway between black and white to the
148	/// eye. Dark mode's base runs up to just below it, light mode's down to it,
149	/// so the base moves through it with no jump.
150	pub const MIDDLE_GREY: u32 = 0x77;
151	
152	/// How far, in channel values, the base can be from the middle grey and still
153	/// feel it: within this, the steps between the greys narrow, so crossing
154	/// between the modes, where the steps turn round, changes as little as it
155	/// can.
156	const MIDDLE_BAND: f32 = 48.;
157	
158	/// How much the steps between the greys narrow on the middle grey itself:
159	/// to half, so the change of mode moves every surface half as far, while
160	/// every step keeps its direction and the greys their order.
161	const MIDDLE_NARROWING: f32 = 0.5;
162	
163	/// How far, in each channel, `step` moves the base: one channel value a step,
164	/// so the slider moves the interface as finely as a colour can.
165	pub fn brightness_shift(step: i32) -> i32 {
166	    step
167	}
168	
169	/// The palette's neutral greys, which brightness moves: every surface, the
170	/// ribbon's, the darkest, and the lines. Text, the accent, the status hues,
171	/// and the overlays' strengths aren't among them.
172	fn greys_mut(p: &mut Palette) -> [&mut u32; 13] {
173	    [
174	        &mut p.well,
175	        &mut p.recessed,
176	        &mut p.base,
177	        &mut p.raised,
178	        &mut p.hover,
179	        &mut p.pressed,
180	        &mut p.selected,
181	        &mut p.overlay,
182	        &mut p.ribbon,
183	        &mut p.ribbon_tabs,
184	        &mut p.darkest,
185	        &mut p.line,
186	        &mut p.edge,
187	    ]
188	}
189	
190	/// The palette's neutral greys, named, as brightness moves them.
191	pub fn greys(palette: &Palette) -> [(&'static str, u32); 13] {
192	    let p = palette;
193	    [
194	        ("well", p.well),
195	        ("recessed", p.recessed),
196	        ("base", p.base),
197	        ("raised", p.raised),
198	        ("hover", p.hover),
199	        ("pressed", p.pressed),
200	        ("selected", p.selected),
201	        ("overlay", p.overlay),
202	        ("ribbon", p.ribbon),
203	        ("ribbon_tabs", p.ribbon_tabs),
204	        ("darkest", p.darkest),
205	        ("line", p.line),
206	        ("edge", p.edge),
207	    ]
208	}
209	
210	/// A channel of `color`, `at` bits up.
211	fn channel(color: u32, at: u32) -> i32 {
212	    ((color >> at) & 0xff) as i32
213	}
214	
215	/// A colour from its red, green, and blue, each clipped to black and white.
216	fn from_channels(f: impl Fn(u32) -> f32) -> u32 {
217	    [16, 8, 0].into_iter().fold(0, |out, at| {
218	        out | ((f(at).round().clamp(0., 255.) as u32) << at)
219	    })
220	}
221	
222	/// `a` laid `amount` of the way toward `b`.
223	fn mix(a: u32, b: u32, amount: f32) -> u32 {
224	    from_channels(|at| {
225	        let (a, b) = (channel(a, at) as f32, channel(b, at) as f32);
226	        a + (b - a) * amount
227	    })
228	}
229	
230	/// How near the middle grey dark or light mode's base is at `step`, from 0,
231	/// out of the middle band, to 1, on the middle grey, easing in and out.
232	fn nearness_to_middle(dark: bool, step: i32) -> f32 {
233	    let reference = if dark { &DARK } else { &LIGHT };
234	    let base = channel(reference.base, 0) + brightness_shift(step);
235	    let t = (1. - (base - MIDDLE_GREY as i32).abs() as f32 / MIDDLE_BAND).clamp(0., 1.);
236	    t * t * (3. - 2. * t)
237	}
238	
239	/// `color`, or as little of the way toward `toward` as it takes for `ok`,
240	/// or `toward` itself if nothing short of it will do.
241	fn legible(color: u32, toward: u32, ok: impl Fn(u32) -> bool) -> u32 {
242	    if ok(color) {
243	        return color;
244	    }
245	    if !ok(toward) {
246	        return toward;
247	    }
248	    let (mut low, mut high) = (0f32, 1f32);
249	    for _ in 0..16 {
250	        let middle = (low + high) / 2.;
251	        if ok(mix(color, toward, middle)) {
252	            high = middle;
253	        } else {
254	            low = middle;
255	        }
256	    }
257	    mix(color, toward, high)
258	}
259	
260	/// Dark or light mode's palette at brightness `step`. Every neutral grey
261	/// moves with the base by the same amount; near the middle grey the steps
262	/// between them narrow, all alike, so the two modes meet there with as
263	/// little change as turning the text round allows. Text and hues
264	/// stay as given unless the base has come too near them to keep the
265	/// contrast the theme asks, and then move only as far toward white, in dark
266	/// mode, or black, in light mode, as it takes. The bevel keeps the lift it
267	/// has at 0.
268	pub fn brightened(dark: bool, step: i32) -> Palette {
269	    let own = if dark { DARK } else { LIGHT };
270	    let shift = brightness_shift(step);
271	    let width = 1. - MIDDLE_NARROWING * nearness_to_middle(dark, step);
272	    let mut p = own;
273	    for grey in greys_mut(&mut p) {
274	        *grey = from_channels(|at| {
275	            let step = (channel(*grey, at) - channel(own.base, at)) as f32;
276	            (channel(own.base, at) + shift) as f32 + step * width
277	        });
278	    }
279	
280	    // Text and hues, only as far from what they were as the contrast needs:
281	    // what the theme asks, or what they had at 0 if that was less.
282	    let toward = if dark { 0xffffff } else { 0x000000 };
283	    let on = |surfaces: &[(u32, u32)], color: u32, asked: f32, moved: u32| {
284	        surfaces
285	            .iter()
286	            .all(|&(now, then)| contrast(moved, now) >= asked.min(contrast(color, then)))
287	    };
288	    let read = [
289	        (p.base, own.base),
290	        (p.recessed, own.recessed),
291	        (p.well, own.well),
292	        (p.overlay, own.overlay),
293	    ];
294	    let controls = [
295	        (p.raised, own.raised),
296	        (p.hover, own.hover),
297	        (p.pressed, own.pressed),
298	        (p.selected, own.selected),
299	    ];
300	    let base = [(p.base, own.base)];
301	    p.text = legible(own.text, toward, |c| {
302	        on(&read, own.text, 4.5, c) && on(&controls, own.text, 4., c)
303	    });
304	    p.text_secondary = legible(own.text_secondary, toward, |c| {
305	        on(&read, own.text_secondary, 4.5, c)
306	    });
307	    p.text_disabled = legible(own.text_disabled, toward, |c| {
308	        on(&base, own.text_disabled, f32::INFINITY, c)
309	    });
310	    for (moved, given) in [
311	        (&mut p.text_tertiary, own.text_tertiary),
312	        (&mut p.accent, own.accent),
313	        (&mut p.success, own.success),
314	        (&mut p.warning, own.warning),
315	        (&mut p.error, own.error),
316	        (&mut p.purple, own.purple),
317	        (&mut p.cyan, own.cyan),
318	        (&mut p.orange, own.orange),
319	    ] {
320	        *moved = legible(given, toward, |c| on(&base, given, 3., c));
321	    }
322	
323	    // The bevel's light and shade, as much lighter and darker as at 0.
324	    let (then, now) = (channel(own.base, 0) as f32, channel(p.base, 0) as f32);
325	    p.bevel_light = (own.bevel_light * (255. - then) / (255. - now).max(1.)).min(1.);
326	    p.bevel_shade = (own.bevel_shade * then / now.max(1.)).min(1.);
327	    p
328	}
329	
330	/// WCAG's contrast ratio between two opaque colours.
331	pub fn contrast(a: u32, b: u32) -> f32 {
332	    let luminance = |c: u32| {
333	        let channel = |shift: u32| {
334	            let v = ((c >> shift) & 0xff) as f32 / 255.;
335	            if v <= 0.04045 {
336	                v / 12.92
337	            } else {
338	                ((v + 0.055) / 1.055).powf(2.4)
339	            }
340	        };
341	        0.2126 * channel(16) + 0.7152 * channel(8) + 0.0722 * channel(0)
342	    };
343	    let (a, b) = (luminance(a), luminance(b));
344	    (a.max(b) + 0.05) / (a.min(b) + 0.05)
345	}
346	
347	/// Whether the text and hues of `p` keep the contrast the theme asks of them
348	/// on its surfaces: primary and secondary text 4.5 to 1 on the base,
349	/// recessed, well, and overlay surfaces; primary text 4 to 1 on controls in
350	/// any state; tertiary text, the status colours, and the accent 3 to 1 on the
351	/// base.
352	#[cfg(test)]
353	pub fn keeps_contrast(p: &Palette) -> bool {
354	    let read = [p.base, p.recessed, p.well, p.overlay];
355	    let controls = [p.raised, p.hover, p.pressed, p.selected];
356	    let hues = [
357	        p.text_tertiary,
358	        p.success,
359	        p.warning,
360	        p.error,
361	        p.accent,
362	        p.orange,
363	    ];
364	    [p.text, p.text_secondary].into_iter().all(|text| {
365	        read.into_iter()
366	            .all(|surface| contrast(text, surface) >= 4.5)
367	    }) && controls
368	        .into_iter()
369	        .all(|control| contrast(p.text, control) >= 4.)
370	        && hues.into_iter().all(|hue| contrast(hue, p.base) >= 3.)
371	}
