373	/// Whether dark or light mode can be at brightness `step`: no grey pushed
374	/// below black or above white, and its base on its own side of the middle
375	/// grey, dark mode's below it and light mode's on it or above.
376	pub fn brightness_allowed(dark: bool, step: i32) -> bool {
377	    let reference = if dark { &DARK } else { &LIGHT };
378	    let base = channel(reference.base, 0) + brightness_shift(step);
379	    let side = if dark {
380	        base < MIDDLE_GREY as i32
381	    } else {
382	        base >= MIDDLE_GREY as i32
383	    };
384	    let clips = greys(reference).into_iter().any(|(_, grey)| {
385	        [16, 8, 0].into_iter().any(|at| {
386	            let moved = channel(grey, at) + brightness_shift(step);
387	            !(0..=255).contains(&moved)
388	        })
389	    });
390	    side && !clips
391	}
