393	/// How far dark or light mode's brightness can go either way: from 0 out to
394	/// the last step allowed before one isn't.
395	pub fn brightness_range(dark: bool) -> std::ops::RangeInclusive<i32> {
396	    let reach = |direction: i32| {
397	        let mut step = 0;
398	        while brightness_allowed(dark, step + direction) {
399	            step += direction;
400	        }
401	        step
402	    };
403	    reach(-1)..=reach(1)
404	}
