406	/// The brightness range of dark or light mode, worked out once.
407	pub fn mode_brightness_range(dark: bool) -> std::ops::RangeInclusive<i32> {
408	    static RANGES: std::sync::LazyLock<[std::ops::RangeInclusive<i32>; 2]> =
409	        std::sync::LazyLock::new(|| [brightness_range(false), brightness_range(true)]);
410	    RANGES[dark as usize].clone()
411	}
