413	/// Every appearance the Brightness slider runs through, darkest first: dark
414	/// mode from its darkest step to its lightest, then light mode from its
415	/// darkest to its lightest, each as whether it is dark mode and its step.
416	pub fn appearances() -> &'static [(bool, i32)] {
417	    static ALL: std::sync::LazyLock<Vec<(bool, i32)>> = std::sync::LazyLock::new(|| {
418	        let dark = mode_brightness_range(true).map(|step| (true, step));
419	        let light = mode_brightness_range(false).map(|step| (false, step));
420	        dark.chain(light).collect()
421	    });
422	    &ALL
423	}
