425	/// Where dark or light mode at brightness `step` falls among the
426	/// appearances, the step kept within what the mode allows.
427	pub fn appearance_index(dark: bool, step: i32) -> usize {
428	    let range = mode_brightness_range(dark);
429	    let step = step.clamp(*range.start(), *range.end());
430	    appearances()
431	        .iter()
432	        .position(|&appearance| appearance == (dark, step))
433	        .expect("every step a mode allows is an appearance")
434	}
