436	/// Dark or light mode's palette at brightness `step`, from every step worked
437	/// out once, so the palette showing can still be borrowed for the life of
438	/// the application.
439	fn shifted(dark: bool, step: i32) -> &'static Palette {
440	    static PALETTES: std::sync::LazyLock<[Vec<Palette>; 2]> = std::sync::LazyLock::new(|| {
441	        let every = |dark: bool| {
442	            mode_brightness_range(dark)
443	                .map(|step| brightened(dark, step))
444	                .collect()
445	        };
446	        [every(false), every(true)]
447	    });
448	    let range = mode_brightness_range(dark);
449	    let step = step.clamp(*range.start(), *range.end());
450	    &PALETTES[dark as usize][(step - range.start()) as usize]
451	}
