475	/// Sets dark or light mode's brightness to `step`, kept within what the mode
476	/// allows, and, if that mode is showing, has every window take it at once:
477	/// only colours change, so nothing is laid out anew. Returns the step taken.
478	pub fn set_brightness(dark: bool, step: i32, cx: &mut App) -> i32 {
479	    let range = mode_brightness_range(dark);
480	    let step = step.clamp(*range.start(), *range.end());
481	    if cx.has_global::<Brightness>() && brightness_of(dark, cx) == step {
482	        return step;
483	    }
484	    let brightness = cx.default_global::<Brightness>();
485	    if dark {
486	        brightness.dark = step;
487	    } else {
488	        brightness.light = step;
489	    }
490	    install_brightness(dark, cx);
491	    if cx.has_global::<Theme>() && cx.theme().is_dark() == dark {
492	        let mode = cx.theme().mode;
493	        Theme::change(mode, None, cx);
494	        cx.refresh_windows();
495	    }
496	    step
497	}
