499	/// Makes gpui-kit's theme for dark or light mode the one for its brightness.
500	fn install_brightness(dark: bool, cx: &mut App) {
501	    if !cx.has_global::<Theme>() || !cx.has_global::<ThemeRegistry>() {
502	        return;
503	    }
504	    let step = brightness_of(dark, cx);
505	    let cached = cx
506	        .try_global::<Brightness>()
507	        .and_then(|b| b.configs.get(&(dark, step)).cloned());
508	    let config = match cached {
509	        Some(config) => config,
510	        None => {
511	            let (mode, registry) = (
512	                if dark {
513	                    ThemeMode::Dark
514	                } else {
515	                    ThemeMode::Light
516	                },
517	                ThemeRegistry::global(cx),
518	            );
519	            let default = if dark {
520	                registry.default_dark_theme()
521	            } else {
522	                registry.default_light_theme()
523	            };
524	            let value = self::config(shifted(dark, step), mode, default);
525	            let config = Rc::new(
526	                serde_json::from_value::<ThemeConfig>(value)
527	                    .expect("the theme's own configuration is valid"),
528	            );
529	            cx.default_global::<Brightness>()
530	                .configs
531	                .insert((dark, step), config.clone());
532	            config
533	        }
534	    };
535	    let theme = Theme::global_mut(cx);
536	    if dark {
537	        theme.dark_theme = config;
538	    } else {
539	        theme.light_theme = config;
540	    }
541	}
