598	/// A bevel's lit and shaded edges' colours, laid over whatever they sit on.
599	pub fn bevel_colors(palette: &Palette) -> (Hsla, Hsla) {
600	    (
601	        white().opacity(palette.bevel_light),
602	        black().opacity(palette.bevel_shade),
603	    )
