606	/// The bevel of a surface at `bounds`, each edge with its colour. Raised, it is
607	/// lit along the top, then down the left beneath that, and shaded along the
608	/// bottom, then up the right above that, so no two overlap; pressed, the lit
609	/// and shaded edges swap. None for a surface too small.
610	pub fn bevel_edges(
611	    bounds: Bounds<Pixels>,
612	    bevel: Bevel,
613	    palette: &Palette,
614	) -> Vec<(Bounds<Pixels>, Hsla)> {
615	    let (width, height) = (bounds.size.width, bounds.size.height);
616	    if width < BEVEL * 2. || height < BEVEL * 2. {
617	        return Vec::new();
618	    }
619	    let (light, shade) = match (bevel, bevel_colors(palette)) {
620	        (Bevel::Raised, (light, shade)) => (light, shade),
621	        (Bevel::Pressed, (light, shade)) => (shade, light),
622	    };
623	    let side = height - BEVEL * 2.;
624	    vec![
625	        (Bounds::new(bounds.origin, size(width, BEVEL)), light),
626	        (
627	            Bounds::new(
628	                point(bounds.left(), bounds.top() + BEVEL),
629	                size(BEVEL, side),
630	            ),
631	            light,
632	        ),
633	        (
634	            Bounds::new(
635	                point(bounds.left(), bounds.bottom() - BEVEL),
636	                size(width, BEVEL),
637	            ),
638	            shade,
639	        ),
640	        (
641	            Bounds::new(
642	                point(bounds.right() - BEVEL, bounds.top() + BEVEL),
643	                size(BEVEL, side),
644	            ),
645	            shade,
646	        ),
647	    ]
648	}
