650	/// The bevel, laid over whatever positioned element it is put in, filling it
651	/// and taking no room or mouse.
652	pub fn bevel(bevel: Bevel, cx: &App) -> impl IntoElement {
653	    let palette = *palette(cx);
654	    canvas(
655	        |_, _, _| {},
656	        move |bounds, _, window, _| {
657	            for (edge, color) in bevel_edges(bounds, bevel, &palette) {
658	                window.paint_quad(fill(edge, color));
659	            }
660	        },
661	    )
662	    .absolute()
663	    .top_0()
664	    .left_0()
665	    .size_full()
666	}
