927	                assert!(lit > 0. && lit < 0.1, "light {lit}");
928	                assert!(shaded > 0. && shaded < 0.03, "shade {shaded}");
929	                assert!(shaded < lit, "shade {shaded} over light {lit}");
930	            }
931	        }
932	        let tiny = Bounds::new(point(px(0.), px(0.)), size(px(1.), px(1.)));
933	        assert!(bevel_edges(tiny, Bevel::Raised, &DARK).is_empty());
934	    }
935	
936	    /// The contrast the theme promises, in both modes.
937	    #[test]
938	    fn both_modes_keep_their_contrast() {
939	        for (name, p) in [("dark", DARK), ("light", LIGHT)] {
940	            let Palette {
941	                base,
942	                recessed,
943	                well,
944	                overlay,
945	                ..
946	            } = p;
947	            for text in [p.text, p.text_secondary] {
948	                for surface in [base, recessed, well, overlay] {
949	                    assert!(
950	                        contrast(text, surface) >= 4.5,
951	                        "{name}: {text:06x} on {surface:06x}"
952	                    );
953	                }
954	            }
955	            for control in [p.raised, p.hover, p.pressed, p.selected] {
956	                assert!(
957	                    contrast(p.text, control) >= 4.,
958	                    "{name}: text on {control:06x}"
959	                );
960	            }
961	            for hue in [
962	                p.text_tertiary,
963	                p.success,
964	                p.warning,
965	                p.error,
966	                p.accent,
967	                p.orange,
968	            ] {
969	                assert!(contrast(hue, base) >= 3., "{name}: {hue:06x} on the base");
970	            }
971	            assert!(
972	                contrast(0xffffff, p.accent_fill) >= 4.5,
973	                "{name}: primary buttons"
974	            );
975	            let edge = contrast(p.edge, base);
976	            assert!((1.4..=1.7).contains(&edge), "{name}: edge {edge}");
977	            assert!(
978	                contrast(p.line, base) < edge,
