994	        assert!(lightness(d.base) < lightness(d.raised));
995	        assert!(lightness(d.raised) < lightness(d.hover));
996	        let l = LIGHT;
997	        assert!(lightness(l.well) > lightness(l.recessed));
998	        assert!(lightness(l.recessed) > lightness(l.base));
999	        assert!(lightness(l.selected) < lightness(l.pressed));
1000	        assert!(lightness(l.pressed) < lightness(l.base));
