            set_custom_colors(CustomColors::default(), cx);
            assert_eq!(reference(true), DARK);
            assert_eq!(appearances().len(), count);
            set_brightness(true, 0, cx);
            assert_eq!(Theme::global(cx).background, color(DARK.base));
        });
    }

